p=np.array([-0.20893091,60.55792418,-131.00473255])
def lab(a,c):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); d_=(ang-np.polyval(p,c)+180)%360-180
    return np.round(d_/45).astype(int), d_-45*np.round(d_/45)
def fit(y,lo,hi,l2=1e-3):
    X=torch.tensor(H[lo-8:hi-8].reshape(-1,128)); Y=torch.tensor(np.tile(y,hi-lo)).float()
    mu=X.mean(0); sd=X.std(0)+1e-6
    w=torch.zeros(128,requires_grad=True); b=torch.zeros(1,requires_grad=True)
    opt=torch.optim.LBFGS([w,b],max_iter=300); pw=(1-Y.mean())/Y.mean()
    def cl():
        opt.zero_grad(); z=((X-mu)/sd)@w+b
        L=torch.nn.functional.binary_cross_entropy_with_logits(z,Y,pos_weight=pw**0.5)+l2*(w**2).sum(); L.backward(); return L
    opt.step(cl)
    return (w/sd).detach().numpy().astype(np.float32),(b-(mu/sd*w).sum()).item()
wp,bp=fit(k0==1,11,16); wm,bm=fit(k0==-1,11,16)
np.save('c7p_detw.npy',wp); np.save('c7m_detw.npy',wm); print('bp',repr(bp),'bm',repr(bm))
